const btnBase = {
  display: "inline-flex",
  alignItems: "center",
  justifyContent: "center",
  width: "28px",
  height: "28px",
  borderRadius: "4px",
  background: "transparent",
  border: "none",
  color: "${n.text}",
  cursor: "pointer",
  padding: "6px",
  transition: "background 0.15s ease",
};

const btnHover = {
  ...btnBase,
  background: "${n.bgHover}",
};

const toolbarStyle = {
  position: "absolute",
  bottom: "12px",
  right: "12px",
  display: "flex",
  alignItems: "center",
  gap: "2px",
  padding: "4px",
  borderRadius: "8px",
  background: "${n.bg}",
  boxShadow: "${n.shadow}",
  backdropFilter: "blur(8px)",
  border: "${n.border}",
  zIndex: 10,
};

